# Experiment 3D: compare subject trends with ggplot2.
source("r/Experiment-03/common.R"); library(ggplot2); library(tidyr); d<-load_students(); long<-pivot_longer(d,cols=all_of(subjects),names_to="Subject",values_to="Score"); p<-ggplot(long,aes(Student,Score,colour=Subject,group=Subject))+geom_line(linewidth=1)+geom_point(size=2.5)+scale_y_continuous(limits=c(0,100),breaks=seq(0,100,20))+labs(title="Student Score Trends",x="Student",y="Score")+theme_minimal()+theme(axis.text.x=element_text(angle=35,hjust=1),legend.position="bottom"); ggsave(save_plot_path("3D_ggplot_line_chart.png"),p,width=9,height=5.5,dpi=180); print(p)
